#include <set>
#include <algorithm>
#include <iostream>

int main() {
    std::set<int> s = {10, 20, 30, 40, 50};

    // CORRECT: O(log N) complexity
    auto it_log = s.find(30);
    if (it_log != s.end()) {
        std::cout << "Found via member find (O(log N)).\n";
    }

    // INCORRECT (Performance Pitfall): O(N) complexity
    // This forces sequential iteration, ignoring the tree structure.
    auto it_linear = std::find(s.begin(), s.end(), 30);
    if (it_linear != s.end()) {
        std::cout << "Found via std::find (O(N)).\n";
    }
}
